create extension if not exists btree_gist;
create table public.items(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(trim(title)) between 3 and 100),category text not null check(category in ('Calculators','Cameras','Projectors','Audio','Books','Costumes','Sports','Tools')),description text not null check(length(trim(description)) between 15 and 2000),price numeric(10,2) not null check(price between 1 and 100000),deposit numeric(10,2) not null default 0 check(deposit between 0 and 1000000),location text not null check(length(trim(location)) between 2 and 100),condition text not null check(condition in ('New','Excellent','Good','Fair')),image_url text not null check(length(image_url)>10),available_from date,available_until date,status text not null default 'published' check(status in ('published','paused','removed','hidden')),created_at timestamptz not null default now(),check(available_until is null or available_from is null or available_until>=available_from));
create table public.rental_requests(id uuid primary key default gen_random_uuid(),item_id uuid not null references public.items(id),renter_id uuid not null references auth.users(id),start_date date not null,end_date date not null,note text not null default '' check(length(note)<=1000),daily_price numeric(10,2) not null check(daily_price>0),deposit numeric(10,2) not null check(deposit>=0),service_fee numeric(10,2) not null check(service_fee>=0),status text not null default 'pending' check(status in ('pending','accepted','declined','cancelled','completed')),created_at timestamptz not null default now(),check(end_date>=start_date));
alter table public.rental_requests add constraint no_accepted_overlap exclude using gist(item_id with =,daterange(start_date,end_date,'[]') with &&) where (status='accepted');
create table public.admins(user_id uuid primary key references auth.users(id) on delete cascade);
create table public.reports(id uuid primary key default gen_random_uuid(),item_id uuid not null references public.items(id),reporter_id uuid not null references auth.users(id),reason text not null check(length(trim(reason)) between 10 and 500),status text not null default 'open' check(status in ('open','resolved')),created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.admins where user_id=(select auth.uid()))$$;
alter table public.items enable row level security;alter table public.rental_requests enable row level security;alter table public.reports enable row level security;alter table public.admins enable row level security;
create policy "published items visible" on public.items for select using(status='published' or owner_id=(select auth.uid()) or public.is_admin());
create policy "owners create" on public.items for insert to authenticated with check(owner_id=(select auth.uid()) and status in ('published','paused'));
create policy "owners update" on public.items for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()) and status in ('published','paused','removed'));
create policy "requests visible to parties" on public.rental_requests for select to authenticated using(renter_id=(select auth.uid()) or exists(select 1 from public.items where items.id=item_id and items.owner_id=(select auth.uid())));
create policy "reporters see own reports or admin" on public.reports for select to authenticated using(reporter_id=(select auth.uid()) or public.is_admin());
create policy "reporters submit" on public.reports for insert to authenticated with check(reporter_id=(select auth.uid()));
create policy "admin self read" on public.admins for select to authenticated using(user_id=(select auth.uid()));
create function public.submit_request_guard() returns trigger language plpgsql security definer set search_path='' as $$declare i public.items%rowtype;begin select * into i from public.items where id=new.item_id; if not found or i.status<>'published' then raise exception 'Item is not available';end if;if i.owner_id<> (select auth.uid()) and new.renter_id=(select auth.uid()) and new.renter_id<>i.owner_id then null;else raise exception 'Invalid renter';end if;if new.start_date < (now() at time zone 'Asia/Manila')::date or (i.available_from is not null and new.start_date<i.available_from) or (i.available_until is not null and new.end_date>i.available_until) then raise exception 'Dates outside availability';end if;if exists(select 1 from public.rental_requests r where r.item_id=new.item_id and r.status='accepted' and daterange(r.start_date,r.end_date,'[]') && daterange(new.start_date,new.end_date,'[]')) then raise exception 'Item already booked for those dates';end if;new.daily_price:=i.price;new.deposit:=i.deposit;new.service_fee:=round((new.end_date-new.start_date+1)*i.price*.08);new.status:='pending';return new;end$$;
create trigger guard_request before insert on public.rental_requests for each row execute function public.submit_request_guard();
create policy "renters submit requests" on public.rental_requests for insert to authenticated with check(renter_id=(select auth.uid()));
create function public.decide_request(p_request_id uuid,p_decision text) returns void language plpgsql security definer set search_path='' as $$declare r public.rental_requests%rowtype;begin if p_decision not in ('accepted','declined') then raise exception 'Invalid decision';end if;select * into r from public.rental_requests where id=p_request_id for update;if not found or r.status<>'pending' then raise exception 'Request no longer pending';end if;if not exists(select 1 from public.items where id=r.item_id and owner_id=(select auth.uid()) and status='published') then raise exception 'Not authorized';end if;update public.rental_requests set status=p_decision where id=p_request_id;end$$;
revoke all on function public.decide_request(uuid,text) from public;grant execute on function public.decide_request(uuid,text) to authenticated;
create function public.moderate_report(p_report_id uuid) returns void language plpgsql security definer set search_path='' as $$declare target uuid;begin if not public.is_admin() then raise exception 'Not authorized';end if;select item_id into target from public.reports where id=p_report_id and status='open' for update;if target is null then raise exception 'Report not found';end if;update public.items set status='hidden' where id=target;update public.reports set status='resolved' where id=p_report_id;end$$;
revoke all on function public.moderate_report(uuid) from public;grant execute on function public.moderate_report(uuid) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('item-photos','item-photos',true,5000000,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "public listing photos" on storage.objects for select using(bucket_id='item-photos');
create policy "users upload own photos" on storage.objects for insert to authenticated with check(bucket_id='item-photos' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "users delete own photos" on storage.objects for delete to authenticated using(bucket_id='item-photos' and (storage.foldername(name))[1]=(select auth.uid())::text);
